package io.knowledgebrain.notification;
import java.io.IOException;import java.util.*;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;import tools.jackson.databind.json.JsonMapper;
@RestController @ConditionalOnProperty(name="brain.notification.api.enabled",havingValue="true") @RequestMapping("/api/spaces/{spaceId}/notifications")
final class NotificationController {
 private final NotificationStore store;private final SpaceAuthorizationClient authority;private final String origin;private final MeterRegistry metrics;
 private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 NotificationController(NotificationStore store,SpaceAuthorizationClient authority,@Value("${brain.notification.browser-origin}")String origin,MeterRegistry metrics){this.store=store;this.authority=authority;this.origin=origin;this.metrics=metrics;}
 static ResponseStatusException bad(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid notification request");}
 static String tag(long v){return "\"nt"+v+"\"";}
 static long number(String raw,long fallback,long max){if(raw==null)return fallback;if(!raw.matches("[1-9][0-9]{0,18}"))throw bad();try{long v=Long.parseLong(raw);if(v>max)throw bad();return v;}catch(NumberFormatException e){throw bad();}}
 static String parent(HttpServletRequest r){var h=Collections.list(r.getHeaders("traceparent"));if(h.size()==1&&h.getFirst().matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")&&!h.getFirst().substring(3,35).equals("0".repeat(32))&&!h.getFirst().substring(36,52).equals("0".repeat(16)))return h.getFirst();return "00-"+UUID.randomUUID().toString().replace("-","")+"-"+UUID.randomUUID().toString().replace("-","").substring(0,16)+"-01";}
 static void parameters(HttpServletRequest r,Set<String> allowed){for(var p:r.getParameterMap().entrySet())if(!allowed.contains(p.getKey())||p.getValue().length!=1)throw bad();if(Set.of("GET","DELETE").contains(r.getMethod())&&(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null))throw bad();}
 static long version(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED);if(h.size()!=1||!h.getFirst().matches("\"nt[1-9][0-9]{0,18}\""))throw bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw bad();}}
 private UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);token=c.getValue();}return authority.authorize(space,token,write,trace);}
 private ResponseEntity<NotificationStore.Notification> response(NotificationStore.Notification v){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(tag(v.version())).body(v);}
 @GetMapping ResponseEntity<NotificationStore.Page> list(@PathVariable String spaceId,HttpServletRequest r){parameters(r,Set.of("state","read","after","limit"));var space=NotificationStore.id(spaceId);authorize(space,r,false,parent(r));metrics.counter("brain.notification.reads","type","catalog").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(space,Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE"),Optional.ofNullable(r.getParameter("read")).orElse("ALL"),r.getParameter("after"),(int)number(r.getParameter("limit"),20,100)));}
 @GetMapping("/{notificationId}") ResponseEntity<NotificationStore.Notification> get(@PathVariable String spaceId,@PathVariable String notificationId,HttpServletRequest r){parameters(r,Set.of());var space=NotificationStore.id(spaceId);var id=NotificationStore.id(notificationId);authorize(space,r,false,parent(r));return response(store.get(space,id));}
 @PutMapping("/{notificationId}") ResponseEntity<NotificationStore.Notification> read(@PathVariable String spaceId,@PathVariable String notificationId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=NotificationStore.id(spaceId);var id=NotificationStore.id(notificationId);String trace=parent(r);var actor=authorize(space,r,true,trace);long expected=version(r);if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE);var bytes=r.getInputStream().readNBytes(1025);if(bytes.length>1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);boolean read;try{var v=json.readTree(bytes);if(v==null||!v.isObject()||v.size()!=1||!v.path("read").isBoolean())throw bad();read=v.path("read").asBoolean();}catch(RuntimeException e){throw bad();}var v=store.change(space,id,actor,expected,read,false,trace.substring(3,35));metrics.counter("brain.notification.changes","type","read-state").increment();return response(v);}
 @DeleteMapping("/{notificationId}") ResponseEntity<NotificationStore.Notification> retire(@PathVariable String spaceId,@PathVariable String notificationId,HttpServletRequest r){parameters(r,Set.of());var space=NotificationStore.id(spaceId);var id=NotificationStore.id(notificationId);String trace=parent(r);var actor=authorize(space,r,true,trace);var v=store.change(space,id,actor,version(r),null,true,trace.substring(3,35));metrics.counter("brain.notification.changes","type","retired").increment();return response(v);}
 @GetMapping("/{notificationId}/revisions") ResponseEntity<List<NotificationStore.Revision>> history(@PathVariable String spaceId,@PathVariable String notificationId,HttpServletRequest r){parameters(r,Set.of("before","limit"));var space=NotificationStore.id(spaceId);var id=NotificationStore.id(notificationId);authorize(space,r,false,parent(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,id,number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)number(r.getParameter("limit"),5,10)));}
}
